// Returns the glyph row index for a code point, or -1 if not covered.
inline int cyrillicGlyphIndex(std::uint32_t codePoint)
{
    if (codePoint >= 0x0410 && codePoint <= 0x044F) return static_cast<int>(codePoint - 0x0410);
    if (codePoint == 0x0401) return 64;
    if (codePoint == 0x0451) return 65;
    return -1;
}

